"""Cuaderno del estudiante 2.º medio, Educación Física y Salud: OA 01 (precisión en habilidades motrices específicas)."""
from __future__ import annotations

from student_content_ma01_b import task
from student_lessons import arith, ex, register


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, r, u, a, z, ch, context, selfcheck, open_task, reinforce, extend):
    """Registra una clase con forma compacta."""
    register(
        oa, n,
        materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": ans} for t, p, s, ans in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers={"recovery": r, "understand": u, "apply": a, "reason": z, "challenge": ch},
        context=context, selfcheck=selfcheck, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


OA = "EF2M OA 01"

# ---------------------------------------------------------------- Clase 1: diagnóstico de precisión (deporte individual)
L(OA, 1,
  "Un espacio libre de 2 m por 2 m con piso seco y antideslizante, una pared o respaldo firme cerca para apoyar la mano, un reloj con segundos, lápiz y papel, y zapatillas atadas o pies descalzos sobre un piso que no resbale. Todo se practica en el suelo y sin saltos altos.",
  "Aprenderé a medir la precisión de un gesto con una pauta de criterios y con el conteo de aciertos. Sirve para saber en qué punto estás en un deporte individual, como la gimnasia rítmica o la natación, antes de perfeccionarlo.",
  ["Sé que las habilidades motrices son de locomoción, manipulación y estabilidad.", "Sé que las habilidades se mejoran con práctica gradual y segura."],
  ["Precisión es hacer un gesto con la técnica correcta y llegar a lo que buscabas. No basta con que «salga»: hay que saber cómo salió. Para medirla usamos una pauta con criterios que se pueden ver. Cada criterio vale 1 punto si se cumple y 0 si no. Un intento es un acierto cuando cumple todos los criterios de la pauta. La precisión se anota como «aciertos de intentos»: por ejemplo, 3 de 5.",
   "En un deporte individual la persona se mide contra su propia ejecución. En gimnasia rítmica, sin aparato, un equilibrio sobre un pie se puede evaluar con tres criterios: apoyo estable del pie, tronco alto y mirada fija en un punto, y final controlado sin pasos extra. En natación, la técnica se estudia primero fuera del agua: posición alargada del cuerpo, movimiento coordinado de brazos y piernas y respiración rítmica. Entrar a una piscina solo corresponde con una persona adulta o un profesor que supervise.",
   "Un diagnóstico de precisión se hace con varios intentos, no con uno solo, porque un intento puede salir bien por casualidad. Se compara tu resultado de hoy con el de otro día, nunca con el de otra persona. Si un gesto te duele, te marea o resbalas, te detienes. Apoyar la mano en la pared o en un respaldo firme es una variante válida y segura, no una trampa."],
  [("precisión", "hacer el gesto con la técnica correcta y llegar a lo que buscabas"), ("criterio", "característica observable que se revisa en un gesto"), ("acierto", "intento que cumple todos los criterios de la pauta"), ("pauta", "lista de criterios con la que se revisa un gesto"), ("diagnóstico", "medición de cómo estás hoy para decidir qué mejorar")],
  [("Contar un acierto", "Una pauta tiene tres criterios: apoyo estable, tronco alto y final controlado. En un intento de equilibrio cumples apoyo estable y tronco alto, pero das un paso extra al terminar. ¿Es un acierto?", ["Hay que cumplir los tres criterios.", "El final no fue controlado, porque diste un paso extra.", "Falta un criterio, así que no es acierto."], "No es un acierto: cumple 2 de 3 criterios"),
   ("Registrar la precisión", "En 6 intentos de equilibrio, los intentos 1, 2, 4 y 5 cumplieron los tres criterios y los intentos 3 y 6 no. ¿Cuál fue tu precisión?", ["Se cuentan los intentos que cumplen todos los criterios: 1, 2, 4 y 5.", "Son 4 aciertos en 6 intentos.", "La precisión se anota 4 de 6."], "4 de 6")],
  [("Evaluar un gesto con un solo intento.", "Un intento puede salir bien o mal por casualidad y no muestra tu nivel.", "Haz varios intentos y cuenta los aciertos."), ("Considerar acierto un intento que cumple solo algunos criterios.", "Un acierto exige cumplir todos los criterios de la pauta.", "Revisa criterio por criterio antes de anotar.")],
  [ex("Un acierto en una pauta de tres criterios, ¿qué exige: A) cumplir los tres criterios; B) cumplir los dos primeros criterios?", "A", "Un acierto es un intento que cumple todos los criterios de la pauta."),
   ex("Estás en equilibrio sobre un pie y sientes un mareo. ¿Qué haces: A) sigo para terminar los intentos; B) me detengo, me apoyo o me siento y aviso a una persona adulta?", "B", "Ante un mareo se detiene la práctica y se pide apoyo para evitar una caída."),
   ex("Para estudiar la técnica de natación en casa, ¿qué puedes practicar: A) la posición del cuerpo y el movimiento de brazos fuera del agua; B) nadar sin supervisión en cualquier piscina?", "A", "Fuera del agua se estudia la técnica sin riesgo, y el agua exige supervisión adulta.")],
  [ex("En un diagnóstico, ¿con qué comparas tu resultado de hoy: A) con el de otra persona; B) con el tuyo de otro día?", "B", "El diagnóstico es un punto de partida propio y no una comparación entre personas."),
   ex("Bruno logró 2 aciertos en 5 intentos de giro lento. ¿Cómo se anota su precisión?", "2 de 5", "Se escriben los aciertos y después los intentos."),
   ex("¿Por qué se hacen varios intentos en un diagnóstico: A) porque uno solo puede salir bien por casualidad; B) porque el primer intento nunca cuenta?", "A", "Con varios intentos el resultado muestra mejor el nivel real.")],
  [arith("Hiciste 4 series de 5 intentos de equilibrio y lograste 14 aciertos en total. ¿Cuántos intentos no fueron aciertos?", "4*5-14", "Se calculan los intentos totales y se restan los aciertos.", " intentos"),
   ex("En un equilibrio, el pie de apoyo se mantiene bien, pero casi siempre das un paso extra al final. ¿Qué criterio debes practicar más: A) el final controlado; B) el apoyo estable?", "A", "El paso extra al terminar muestra que falla el final controlado."),
   ex("Al hacer un giro de media vuelta tu cabeza se va hacia un lado y pierdes el equilibrio. ¿Qué ajuste ayuda: A) mirar un punto fijo a la altura de los ojos; B) mirar el piso justo debajo de los pies?", "A", "Un punto fijo da una referencia y ayuda a mantener el equilibrio al girar.")],
  [ex("Marta tuvo 3 de 5 aciertos el lunes y 4 de 5 el jueves en el mismo equilibrio. ¿Su precisión mejoró, empeoró o quedó igual?", "Mejoró", "Pasó de 3 aciertos a 4 en la misma cantidad de intentos."),
   ex("Iván acertó 3 de 3 intentos, todos hechos muy lento y apoyado en la pared. ¿Basta para decir que domina el equilibrio sin apoyo: sí o no?", "No", "El resultado se obtuvo con una variante de apoyo y no muestra el equilibrio libre.")],
  [arith("Una pauta da 1 punto por cada uno de sus 3 criterios en cada intento. Rafaela obtuvo 3, 2, 3, 1 y 3 puntos en cinco intentos. ¿Cuántos puntos sumó?", "3+2+3+1+3", "Se suman los puntos de los cinco intentos.", " puntos"),
   arith("Cada serie dura 2 minutos y entre una serie y otra pausas 1 minuto. Si haces 4 series, ¿cuántos minutos dura todo?", "4*2+3*1", "Hay 4 series y 3 pausas entre ellas.", " minutos")],
  [ex("Una semana Daniela hizo 10 intentos y acertó 7; la semana siguiente hizo 5 y acertó 4. Con la forma «aciertos de intentos», ¿en qué semana tuvo más aciertos: la primera o la segunda?", "La primera", "Con 7 aciertos supera a los 4 de la segunda, aunque hizo distinta cantidad de intentos."),
   ex("Sofía anotó para un equilibrio: apoyo estable sí, tronco alto no, final controlado sí. ¿Cuántos puntos obtuvo?", "2", "Se suma 1 por cada criterio cumplido: apoyo estable y final controlado."),
   ex("Un compañero de curso se tambalea más que tú. ¿Qué haces con tu diagnóstico: A) me burlo; B) lo uso solo para decidir qué practicar yo?", "B", "El diagnóstico es personal y se respeta a todas las personas.")],
  [ex("En Educación Física: ¿qué es un acierto en una pauta de criterios?", "Un intento que cumple todos los criterios", "Esa es la definición de la clase."),
   ex("¿Cómo se anota la precisión de 5 aciertos en 8 intentos?", "5 de 8", "Se escriben los aciertos y luego los intentos."),
   ex("¿Qué haces si sientes dolor o mareo durante un intento?", "Me detengo y aviso a una persona adulta", "La seguridad va antes que terminar los intentos.")],
  ("Haz tu diagnóstico de equilibrio con esta pauta de tres criterios: (1) apoyo estable del pie, (2) tronco alto con la mirada en un punto fijo, (3) final controlado sin pasos extra. Haz 5 intentos de equilibrio sobre un pie, con el otro pie levantado a la altura de la rodilla, y sostén 5 segundos en cada intento. Puedes tocar la pared con la punta de los dedos si lo necesitas. Descansa 30 segundos entre intentos. Anota en una tabla 1 o 0 por criterio y el total de aciertos, y escribe qué criterio vas a perfeccionar.",
   "Intento 1: 1, 1, 1 (acierto). Intento 2: 1, 0, 1. Intento 3: 1, 1, 0. Intento 4: 1, 1, 1 (acierto). Intento 5: 1, 0, 1. Precisión: 2 de 5. Voy a perfeccionar el tronco alto con la mirada fija, porque falló dos veces.",
   ["usa los tres criterios en los cinco intentos", "anota 1 o 0 en cada criterio", "calcula los aciertos y elige un criterio a perfeccionar"],
   ["tabla de cinco intentos", "aciertos como «de 5»", "un criterio elegido con su razón"],
   ["hacer un solo intento", "comparar tu resultado con el de otra persona", "practicar sobre un piso resbaladizo o con objetos cerca"],
   "Cuenta qué variante de apoyo usaste y por qué te ayudó."),
  "Haz solo 3 intentos y revisa los tres criterios en cada uno.",
  "Elige gimnasia rítmica o natación y anota tres criterios observables para revisar la técnica de un gesto.")

# ---------------------------------------------------------------- Clase 2: seleccionar el golpe (deporte de oposición)
L(OA, 2,
  "Un globo, un espacio libre de 3 m por 3 m con piso seco, un trozo de cinta o un papel de 30 cm como blanco en el piso, lápiz y papel, y zapatillas atadas. Se practica sin raqueta, golpeando el globo con la palma abierta y sin ningún contacto con otras personas.",
  "Aprenderé a elegir y ejecutar con precisión el golpe adecuado en un deporte de oposición, como el bádminton o el tenis de mesa. Sirve para decidir en pocos segundos qué golpe usar y mandar el objeto hacia donde quieres.",
  ["Sé medir la precisión con aciertos de intentos.", "Sé que un deporte de oposición enfrenta a dos personas separadas por una red."],
  ["En un deporte de oposición cada golpe responde a una situación. En bádminton hay tres golpes básicos. El despeje manda el volante alto y lejos, hacia el fondo de la cancha rival. La dejada lo manda suave y corto, justo detrás de la red. El remate es un golpe fuerte hacia abajo y solo se puede dar si el volante viene alto. El volante es el objeto con plumas o plástico que se golpea.",
   "Antes de golpear se hace el mismo orden: mirar, ubicarse y ejecutar. Miras la altura del volante y dónde está tu rival. Te ubicas en la postura base, con las rodillas ligeramente flexionadas y el peso en la punta de los pies. Ejecutas con el codo alto, contacto delante del cuerpo y un final que te devuelve al centro de tu lado de la cancha. En tenis de mesa el orden es el mismo, pero la pelota rebota en la mesa y la elección depende de si rebota corta o larga.",
   "Precisión no es golpear fuerte. Un golpe preciso llega al lugar elegido con el mismo gesto cada vez. En esta clase lo practicas sin raqueta: golpeas un globo con la palma abierta hacia un blanco marcado en el piso y haces sombra, es decir, repites el gesto sin objeto para fijar la técnica. Si el globo se te va hacia muebles o hacia otra persona, cambias de lugar y retomas con más espacio."],
  [("despeje", "golpe alto que lleva el volante al fondo de la cancha rival"), ("dejada", "golpe suave y corto que cae justo detrás de la red"), ("remate", "golpe fuerte hacia abajo, posible solo con volante alto"), ("postura base", "posición con rodillas flexionadas y peso adelante, lista para moverse"), ("sombra", "repetición del gesto sin objeto para fijar la técnica")],
  [("Elegir el golpe", "El volante viene alto, justo sobre tu cabeza, y quieres mandarlo con fuerza hacia abajo. ¿Qué golpe eliges: despeje, dejada o remate?", ["Un golpe fuerte hacia abajo necesita un volante alto.", "El volante viene alto.", "El golpe es el remate."], "Remate"),
   ("Volver a la postura", "Después de un despeje, ¿hacia dónde regresas en tu mitad de la cancha?", ["El golpe ya terminó y viene la respuesta del rival.", "Desde el centro llegas a más lugares.", "Regresas al centro, en postura base."], "Al centro de tu mitad, en postura base")],
  [("Golpear siempre lo más fuerte que se puede.", "La fuerza sin dirección manda el objeto fuera o a un lugar fácil para el rival.", "Elige el golpe según la altura y busca llegar al lugar elegido."), ("Quedarse parado después de golpear.", "Si no vuelves al centro, el siguiente golpe llega más lejos.", "Regresa a la postura base después de cada golpe.")],
  [ex("El despeje lleva el volante: A) alto y lejos, hacia el fondo; B) suave y corto, detrás de la red. ¿Cuál es?", "A", "El despeje es el golpe alto y profundo."),
   ex("Para dar un remate, ¿cómo debe venir el volante: A) alto; B) a la altura de las rodillas?", "A", "El remate baja desde arriba y solo se puede dar con volante alto."),
   ex("Practicas sin raqueta y repites el gesto sin globo para fijar la técnica. ¿Cómo se llama esa práctica?", "Sombra", "La sombra es repetir el gesto sin objeto.")],
  [ex("Quieres que el volante caiga suave y corto detrás de la red. ¿Qué golpe usas?", "Dejada", "La dejada cae cerca de la red con poca velocidad."),
   ex("Tu rival está cerca de la red y quieres sacarlo de ahí con un golpe que lo obligue a ir atrás. ¿Qué golpe es más adecuado: A) despeje; B) dejada?", "A", "El despeje manda el volante alto y al fondo, lejos de quien está en la red."),
   ex("En el gesto del remate, ¿dónde ocurre el contacto con el volante: A) arriba y delante del cuerpo; B) detrás de la cabeza?", "A", "Contactar arriba y adelante permite dirigir el golpe hacia abajo y mantener el equilibrio.")],
  [ex("Practicaste 8 golpes de palma al globo hacia el blanco del piso y 5 cayeron sobre el blanco. ¿Cómo anotas tu precisión?", "5 de 8", "Se escriben los aciertos y luego los intentos."),
   arith("Haces 3 series de 6 golpes con el globo hacia el blanco. ¿Cuántos golpes das en total?", "3*6", "Se multiplican las series por los golpes de cada una.", " golpes"),
   ex("Tu golpe sale siempre largo, fuera del blanco, aunque el gesto se ve bien. ¿Qué ajustas: A) la fuerza del golpe; B) la postura base?", "A", "Si el gesto es correcto y el golpe pasa de largo, el ajuste es la fuerza.")],
  [ex("Diego dice que el mejor golpe es siempre el remate porque es el más fuerte. ¿Tiene razón: sí o no?", "No", "El golpe se elige según la situación; un remate no sirve con un volante bajo."),
   ex("Elisa golpea con el codo bajo y el globo sale sin dirección. ¿Qué parte del gesto corriges: A) subir el codo y contactar delante del cuerpo; B) golpear con más fuerza?", "A", "Un codo alto y un contacto adelante dan dirección al golpe.")],
  [arith("En 4 series de 5 golpes al blanco acertaste 13. ¿Cuántos golpes no cayeron en el blanco?", "4*5-13", "Se calculan los golpes totales y se restan los aciertos.", " golpes"),
   ex("Un volante viene alto y tu rival está en el fondo de la cancha. ¿Qué golpe lo obliga a moverse hacia adelante: A) la dejada; B) el despeje?", "A", "La dejada cae corta, cerca de la red, y obliga a quien está en el fondo a avanzar.")],
  [ex("Para practicar un golpe alto en casa, un amigo te propone hacerlo en el pasillo con un jarrón en la repisa. ¿Qué respondes: A) prefiero un espacio libre sin objetos frágiles; B) lo hacemos igual?", "A", "Un espacio libre evita golpes con objetos que se puedan caer."),
   ex("Una compañera repite 6 golpes de dejada y los 6 caen junto al blanco, pero siempre con el mismo gesto lento. ¿Qué puede probar después: A) el mismo gesto con un poco más de velocidad; B) cambiar a otro gesto distinto sin haber dominado este?", "A", "Cuando el gesto es preciso y lento, se sube la velocidad de forma gradual.")],
  [ex("En Educación Física: ¿qué es la postura base?", "Una posición con rodillas flexionadas y peso adelante, lista para moverse", "Esa es la definición de la clase."),
   ex("¿Qué golpe se da con fuerza hacia abajo cuando el volante viene alto?", "El remate", "Es el golpe fuerte de arriba hacia abajo."),
   ex("¿Qué haces si el globo se va hacia un mueble o una persona?", "Cambio de lugar y retomo con más espacio", "Practicar donde hay obstáculos puede causar golpes.")],
  ("Practica con un globo y un blanco de 30 cm marcado en el piso a 2 m de ti. Haz estas tres series: (1) 6 golpes suaves con la palma que caigan cerca del blanco, como una dejada; (2) 6 golpes altos que suban por encima de tu cabeza, como un despeje; (3) 6 repeticiones de sombra del remate, sin globo, con el codo alto. Anota cuántos golpes de las series 1 y 2 cayeron en el blanco o subieron como pedía la consigna, y qué cambiarías en el gesto.",
   "Serie 1: 4 de 6 cerca del blanco. Serie 2: 5 de 6 altos. Sombra del remate: 6 repeticiones con el codo alto. Voy a cambiar la fuerza de la serie 1, porque dos golpes pasaron de largo.",
   ["practica las tres series con el globo y la sombra", "cuenta aciertos de cada serie", "elige un cambio para mejorar el gesto"],
   ["registro de las tres series", "aciertos como «de 6»", "un ajuste concreto"],
   ["golpear sin mirar el globo", "dar el remate con un globo bajo", "practicar cerca de muebles"],
   "Explica cómo decidiste la fuerza de la serie 1."),
  "Haz solo la serie 2 y cuenta cuántos golpes subieron por encima de tu cabeza.",
  "Mira la descripción de un golpe de bádminton y escribe en una frase en qué situación lo usarías.")

# ---------------------------------------------------------------- Clase 3: combinar habilidades en un deporte de colaboración
L(OA, 3,
  "Un espacio libre de 3 m por 3 m con piso seco, cinta o papeles para marcar 6 puntos en el piso, una toalla enrollada, una persona de tu casa que pueda observar, lápiz y papel. Se practica solo en el suelo: el kayak y la escalada reales se hacen únicamente con instructor y equipo de seguridad.",
  "Aprenderé a combinar habilidades en un deporte de colaboración, como el kayak en pareja y la escalada con cordada. Sirve para coordinar tus movimientos con los de otra persona y mantener la seguridad.",
  ["Sé elegir el golpe según la situación.", "Sé que una secuencia tiene preparación, acción y recuperación."],
  ["En un deporte de colaboración dos o más personas trabajan juntas hacia una meta, sin rival directo. En kayak de dos personas ambas reman a un ritmo común. La palada tiene cuatro fases: entrada de la pala al agua, tracción, salida y recuperación. Quien va adelante marca el ritmo y quien va atrás lo sigue. Sin ritmo común el kayak se desvía y se pierde fuerza.",
   "En escalada el cuidado de la pareja es parte de la técnica. Quien escala se mueve con tres puntos de apoyo: mantiene tres apoyos firmes, entre manos y pies, y mueve solo uno a la vez. Quien asegura sostiene la cuerda y vigila. Antes de empezar, ambas personas revisan juntas el arnés y la cuerda, y avisan lo que van a hacer. Todo esto se aprende en un recinto con instructor, con equipo certificado y chaleco salvavidas en el caso del kayak.",
   "En casa puedes practicar la combinación sin riesgo. Para el ritmo de remo, siéntate en el suelo con las piernas estiradas, toma una toalla enrollada con ambas manos y gira el tronco en cada tracción, contando 1-2-1-2 en voz alta. Para la escalada, marca 6 puntos de cinta en el piso, sin altura, y recorre el camino moviendo un solo apoyo a la vez entre ellos, con los otros tres apoyos firmes."],
  [("colaboración", "trabajo conjunto de varias personas hacia una meta común"), ("palada", "movimiento completo de la pala en el agua"), ("tres puntos de apoyo", "mantener tres apoyos firmes y mover solo uno a la vez"), ("cordada", "pareja o grupo de personas unidas por una cuerda al escalar"), ("ritmo común", "cuenta compartida que permite moverse a la vez")],
  [("Ordenar las fases", "Una palada tiene cuatro fases: entrada, tracción, salida y recuperación. ¿Cuál va justo después de la tracción?", ["La tracción es el momento en que la pala empuja el agua.", "Después hay que sacar la pala del agua.", "La salida."], "La salida"),
   ("Aplicar tres puntos de apoyo", "Una persona escala con las dos manos y el pie derecho firmes. Quiere mover el pie izquierdo. ¿Cumple la regla si lo mueve ahora?", ["Se mantienen tres apoyos y se mueve uno.", "Ahora hay tres apoyos firmes: dos manos y el pie derecho.", "Sí, puede mover el pie izquierdo porque solo se mueve un apoyo."], "Sí, porque conserva tres apoyos firmes")],
  [("Remar cada persona a su propio ritmo.", "Sin un ritmo común el kayak se desvía y se pierde fuerza.", "Sigue la cuenta de la persona que marca el ritmo."), ("Mover dos apoyos a la vez al escalar.", "Quedas con solo dos apoyos y aumenta el riesgo de caer.", "Mueve un apoyo cada vez.")],
  [ex("En un kayak de dos personas, ¿quién marca el ritmo: A) quien va adelante; B) quien va atrás?", "A", "La persona de adelante marca el ritmo y la de atrás lo sigue."),
   ex("En la regla de tres puntos de apoyo, ¿cuántos apoyos mueves a la vez: A) uno; B) dos?", "A", "Se mantienen tres apoyos y se mueve uno solo."),
   ex("¿Quién puede enseñarte kayak o escalada de verdad: A) una persona con formación e instructor y equipo certificado; B) cualquier amigo con su cuerda?", "A", "Estas actividades exigen instructor y equipo certificado por el riesgo que tienen.")],
  [ex("Antes de escalar, ambas personas revisan juntas el arnés y la cuerda. ¿Para qué sirve esa revisión conjunta: A) para que la cordada empiece segura; B) solo para cumplir un trámite?", "A", "Una revisión entre dos disminuye la posibilidad de que se pase por alto una falla."),
   ex("Remas sentada en el piso con una toalla enrollada. ¿Qué parte del cuerpo gira para dar la tracción: A) el tronco; B) solo las muñecas?", "A", "La tracción usa el giro del tronco y no solo los brazos."),
   ex("Dos personas reman con una cuenta 1-2 distinta cada una. ¿Qué pasa con el kayak: A) se desvía; B) avanza recto?", "A", "Sin ritmo común las paladas empujan en momentos distintos.")],
  [arith("Remas 4 tandas de 12 paladas simuladas con la toalla. ¿Cuántas paladas haces en total?", "4*12", "Se multiplican las tandas por las paladas de cada una.", " paladas"),
   ex("Recorres 3 veces el camino de 6 puntos de cinta, moviendo un apoyo cada vez. En cada recorrido pisas todos los puntos una vez. ¿Cuántas pisadas de punto haces en total?", "18", "Son 6 puntos por 3 recorridos.", "6*3"),
   ex("Tu pareja de práctica dice «voy a cambiar la mano derecha». ¿Qué respondes antes de que lo haga: A) «recibido, avanza»; B) nada?", "A", "En la cordada se avisa lo que se va a hacer y la otra persona confirma.")],
  [ex("Camila piensa que en la escalada solo importa la fuerza de los brazos. ¿Tiene razón: sí o no?", "No", "La escalada también depende de las piernas, el equilibrio y los tres puntos de apoyo, no solo de los brazos."),
   ex("En un kayak doble una persona va muy fuerte y la otra suave, y el kayak gira. ¿Qué ajustan: A) unificar la fuerza y el ritmo; B) remar los dos más fuerte?", "A", "Igualar fuerza y ritmo corrige el giro y no se trata de remar más fuerte.")],
  [arith("Haces 5 series de 8 giros de tronco con la toalla y entre series descansas 30 segundos, 4 veces. ¿Cuántos segundos descansas en total?", "4*30", "Entre 5 series hay 4 pausas de 30 segundos.", " segundos"),
   ex("Practicas una cordada en casa: una persona se mueve por los puntos de cinta y otra observa con una lista de 3 criterios (un apoyo cada vez, tres apoyos firmes, aviso en voz alta). En un recorrido cumplió el primero y el tercero. ¿Cuántos criterios cumplió?", "2", "Cumplió dos de los tres criterios de la lista.")],
  [ex("En una salida de curso con instructor, una compañera se pone el chaleco salvavidas a medias antes de subir al kayak. ¿Qué haces: A) le aviso a la persona instructora para que lo revise; B) no digo nada para no molestar?", "A", "Un chaleco mal puesto es un riesgo y la persona instructora debe revisarlo."),
   ex("En una cordada, quien escala dice «¡voy a cambiar el pie izquierdo!». ¿Qué debe responder quien asegura: A) «recibido» después de comprobar la cuerda; B) nada, para no distraer?", "A", "Quien asegura confirma después de mirar la cuerda, para que el aviso sirva de algo.")],
  [ex("En Educación Física: ¿qué es una cordada?", "Una pareja o grupo unido por una cuerda al escalar", "Esa es la definición de la clase."),
   ex("¿Cuántos apoyos firmes se mantienen en la regla de tres puntos?", "Tres", "Se mantienen tres apoyos y se mueve uno."),
   ex("¿Qué haces si alguien te propone probar escalada o kayak solos, sin instructor?", "No lo hago y lo hablo con una persona adulta", "Estas actividades requieren instructor y equipo de seguridad.")],
  ("Practica con una persona de tu casa estas dos tareas en el piso. (1) Remo en seco: sentados frente a frente, cada uno con una toalla enrollada, hacen 3 series de 10 paladas con la cuenta 1-2 en voz alta; una de las dos personas marca el ritmo con la cuenta y la otra la sigue. (2) Camino de cinta: marca 6 puntos y recórrelos con tres apoyos firmes, moviendo uno a la vez; la otra persona revisa estos criterios: un apoyo cada vez, final controlado y aviso en voz alta. Anota cuántos recorridos cumplieron los tres criterios de 4 intentos.",
   "Remo: 3 series de 10 con ritmo común. Camino: 4 intentos, 3 cumplieron los tres criterios y 1 falló el aviso en voz alta. Voy a practicar avisar antes de cada cambio.",
   ["practica las dos tareas con la cuenta y con la lista de criterios", "registra los intentos que cumplen los tres criterios", "explica qué ajustarás en el trabajo en pareja"],
   ["registro de series", "intentos cumplidos de 4", "un ajuste para la coordinación"],
   ["remar a ritmos distintos", "mover dos apoyos a la vez", "hacer escalada o kayak reales sin instructor"],
   "Cuenta cómo se pusieron de acuerdo para marcar el ritmo."),
  "Haz solo el camino de cinta, con 2 recorridos, mirando que se mueva un solo apoyo.",
  "Escribe tres señales que ayudan a dos personas a trabajar a la vez, como una cuenta o una palabra de aviso.")

# ---------------------------------------------------------------- Clase 4: aplicar en un deporte de oposición/colaboración
L(OA, 4,
  "Un espacio libre de 4 m por 3 m con piso seco, un globo o un balón blando (o calcetines enrollados en forma de bola), cinta para marcar una línea, una persona de tu casa para pasarse el objeto, lápiz y papel, y zapatillas atadas. Sin contacto físico, sin empujones y sin tacleadas.",
  "Aprenderé a aplicar con precisión un pase y una recepción en deportes de oposición y colaboración, como el fútbol, el vóleibol y el rugby. Sirve para que el objeto llegue donde tu compañera o compañero lo espera.",
  ["Sé que una secuencia tiene preparación, acción y recuperación.", "Sé que en la colaboración se avisa y se sigue un ritmo común."],
  ["En los deportes de oposición y colaboración dos equipos juegan a la vez: dentro de cada equipo se colabora y entre equipos se compite. Un pase preciso llega al lugar y al momento en que lo espera la otra persona. En fútbol se pasa con el borde interno del pie, con el pie de apoyo junto al balón y el cuerpo mirando hacia el destino. El control del balón se hace con la parte plana del pie.",
   "En vóleibol el pase de antebrazos se hace con los brazos juntos y estirados, y las rodillas flexionadas. Un equipo puede dar hasta tres toques antes de pasar la pelota al otro lado. En rugby el pase con las manos debe ir hacia atrás o hacia un costado, no hacia adelante. En esta clase todo se practica a una distancia de 3 m, sin velocidad excesiva y sin acercarte a la otra persona.",
   "Para pasar con precisión se siguen cuatro pasos: mirar a quien recibe, ubicar el cuerpo, ejecutar el pase con un gesto completo y volver a la postura base. Quien recibe también trabaja: se coloca, muestra las manos o el pie y controla el objeto antes de devolverlo. Si el pase sale fuera de control, se ajusta una sola cosa a la vez: la dirección, la fuerza o la altura."],
  [("pase", "envío del objeto a una compañera o compañero"), ("recepción", "control del objeto que llega"), ("borde interno", "parte lateral interior del pie con la que se da un pase preciso"), ("antebrazos", "parte del brazo, desde la muñeca al codo, con la que se recibe en vóleibol"), ("toque", "contacto de un equipo con la pelota")],
  [("Elegir cuántos toques", "En vóleibol tu equipo ya dio dos toques a la pelota. ¿Cuántos toques puede dar todavía antes de pasarla al otro lado?", ["El máximo es tres toques por equipo.", "Ya se dieron dos.", "Queda uno."], "Uno"),
   ("Corregir un pase", "En un pase de fútbol a 3 m el balón sale siempre desviado a la izquierda. Tu pie de apoyo queda muy atrás del balón. ¿Qué ajustas primero?", ["El pie de apoyo debe estar junto al balón.", "Si queda atrás, el cuerpo se abre y desvía el pase.", "Ubicar el pie de apoyo junto al balón."], "Pongo el pie de apoyo junto al balón")],
  [("Pasar sin mirar a quien recibe.", "No sabes dónde está ni a qué velocidad debe llegar el objeto.", "Mira a la persona antes de pasar."), ("Pasar el objeto con la mayor fuerza posible.", "La fuerza sin control hace que el pase llegue desviado o que no se pueda recibir.", "Elige la fuerza para que llegue a su alcance.")],
  [ex("En rugby, ¿hacia dónde debe ir un pase con las manos: A) hacia atrás o a un costado; B) hacia adelante?", "A", "En rugby el pase con las manos no puede ir hacia adelante."),
   ex("En vóleibol, ¿cuántos toques da como máximo un equipo antes de pasar la pelota al otro lado: A) tres; B) cuatro?", "A", "El máximo es de tres toques por equipo."),
   ex("En un pase de fútbol con el borde interno, ¿dónde debe estar el pie de apoyo: A) junto al balón; B) lejos del balón?", "A", "El pie de apoyo junto al balón da dirección y equilibrio.")],
  [ex("Quien recibe un pase en casa, ¿qué hace además de esperar: A) se coloca y muestra las manos o el pie; B) se queda quieta mirando al piso?", "A", "Quien recibe colabora: se ubica y deja claro dónde espera el objeto."),
   ex("Tu pase de globo llega siempre bajo y a los pies de tu compañera. ¿Qué ajustas: A) la altura del pase; B) el color del globo?", "A", "El error es la altura: el pase debe llegar donde se pueda recibir."),
   ex("Dos equipos juegan vóleibol. ¿Qué tipo de deporte es: A) de oposición y colaboración; B) de colaboración sin rival?", "A", "Hay colaboración dentro de cada equipo y oposición entre equipos.")],
  [arith("Pasas 5 series de 8 pases a 3 m. ¿Cuántos pases haces en total?", "5*8", "Se multiplican las series por los pases de cada una.", " pases"),
   ex("De 12 pases a 3 m, 9 llegaron a la zona marcada con cinta. ¿Cómo anotas la precisión?", "9 de 12", "Se escriben los aciertos y luego los intentos."),
   ex("Practicas con una persona de tu casa y el pase se va muy lejos. ¿Qué ajustas primero: A) la fuerza; B) el número de pases por serie?", "A", "Un pase largo suele deberse a demasiada fuerza.")],
  [ex("Ricardo dice que en un deporte de colaboración solo importa quien pasa. ¿Tiene razón: sí o no?", "No", "También importa quien recibe, porque se ubica y controla el objeto."),
   ex("Paula tuvo 5 de 10 pases precisos con mucha fuerza y 8 de 10 con fuerza moderada. ¿Qué fuerza le da más precisión?", "La fuerza moderada", "Con fuerza moderada tuvo 8 aciertos contra 5.")],
  [arith("En 6 series de 6 pases a 3 m lograste 27 aciertos. ¿Cuántos pases no fueron precisos?", "6*6-27", "Se calculan los pases totales y se restan los aciertos.", " pases"),
   ex("Un pase de vóleibol a 3 m sale demasiado alto. Tienes tres opciones: A) empujo con menos fuerza y mantengo los antebrazos más bajos; B) estiro las piernas y empujo más. ¿Cuál corrige el exceso de altura?", "A", "Menos empuje y antebrazos más bajos mandan la pelota menos alto.")],
  [ex("En un partido en el patio, una compañera pasa el balón muy fuerte y tu pareja de equipo se asusta. ¿Qué haces: A) le propongo bajar la fuerza y probar de nuevo; B) la reprendo delante del equipo?", "A", "Los ajustes se proponen con respeto, porque el equipo colabora."),
   ex("Tienes 3 minutos para practicar pases y otros 3 para que tu pareja practique. Si hacen 2 rondas cada uno, ¿cuántos minutos practican entre las dos personas?", "12", "Cada persona practica 3 minutos por 2 rondas, es decir 6 minutos, y son dos personas.")],
  [ex("En Educación Física: ¿qué es la recepción?", "El control del objeto que llega", "Esa es la definición de la clase."),
   ex("¿Cuántos pasos tiene un pase preciso en la clase?", "Cuatro", "Son mirar, ubicar el cuerpo, ejecutar y volver a la postura base."),
   ex("¿Qué haces si la otra persona se acerca demasiado durante la práctica?", "Me detengo y retomamos a la distancia de 3 m", "La distancia evita choques.")],
  ("Elige una opción y practícala a 3 m con una persona de tu casa: (a) fútbol con un balón blando o un calcetín en bola, pase con el borde interno; (b) vóleibol con un globo, pase de antebrazos; (c) rugby con una toalla enrollada, pase con las manos hacia un costado. Marca con cinta una zona de 1 m por 1 m delante de quien recibe. Haz 3 series de 6 pases y anota cuántos llegan a la zona. Cambien de rol y después escribe qué ajustarás.",
   "Elegí (b), globo. Serie 1: 3 de 6. Serie 2: 4 de 6. Serie 3: 5 de 6. Mis pases salían bajos al inicio, entonces flexioné más las rodillas y mejoró la altura. Mañana ajustaré la dirección.",
   ["practica 3 series de 6 pases a 3 m", "cuenta cuántos llegan a la zona", "cambia solo una cosa por vez y explícalo"],
   ["registro de tres series", "aciertos de 6 en cada serie", "un ajuste con su efecto"],
   ["pasar sin mirar", "acercarse a la otra persona o hacer contacto", "cambiar varias cosas a la vez"],
   "Cuenta cómo se avisaron antes de cada pase."),
  "Haz solo una serie de 6 pases y cuenta cuántos llegan a la zona.",
  "Dibuja una cancha de tu deporte favorito del grupo y marca dos lugares desde donde un pase sería más difícil de recibir.")

# ---------------------------------------------------------------- Clase 5: evaluar y ajustar en una danza
L(OA, 5,
  "Un espacio libre de 3 m por 3 m con piso seco y liso, lápiz y papel, un reloj con segundos o la cuenta en voz alta, zapatillas atadas o calcetines con suela antideslizante, y una persona de tu casa que pueda observar. La música es opcional: puedes marcar el ritmo con palmas.",
  "Aprenderé a evaluar con una pauta y a ajustar el desempeño en una danza, folclórica o popular. Sirve para que tus pasos queden con el ritmo y la dirección que tiene la coreografía.",
  ["Sé medir la precisión con aciertos de intentos.", "Sé que la fluidez es pasar de una habilidad a la siguiente sin pausas largas."],
  ["La danza es una práctica motriz con ritmo y expresión. Puede ser folclórica, es decir, propia de un lugar y de una tradición, o popular, de uso actual en fiestas y encuentros. Los pasos concretos de una danza folclórica los enseñan quienes la conocen, como el profesor o una persona de la comunidad. Aquí practicas el análisis con un patrón de pasos simple que nos sirve para todas las danzas.",
   "En danza la precisión se evalúa con tres criterios: tiempo, es decir, caer en la cuenta correcta; espacio, es decir, ir en la dirección y distancia indicadas; y cuerpo, es decir, mantener una postura estable con rodillas ligeramente flexionadas. Tu patrón de ejemplo es de 8 tiempos: 2 pasos laterales a la derecha, un cierre de pies, 2 pasos laterales a la izquierda, un cierre y una pausa de 2 tiempos. Cuenta del 1 al 8 en voz alta.",
   "Para ajustar con evidencia, observa un intento, anota qué criterio falló y cambia solo una cosa en el siguiente. Si cambias varias cosas a la vez, no sabrás cuál produjo la mejora. Empieza lento, sube la velocidad cuando salga limpio tres veces seguidas y detente si sientes dolor o mareo. Una persona de tu casa puede mirar y marcar los criterios en una lista."],
  [("danza folclórica", "baile propio de un lugar y de una tradición"), ("danza popular", "baile de uso actual en fiestas y encuentros"), ("tiempo", "cuenta o golpe del ritmo en que cae cada paso"), ("espacio", "dirección y distancia por donde se mueve el cuerpo"), ("ajuste", "cambio de una sola cosa para mejorar el siguiente intento")],
  [("Evaluar con la pauta", "En un intento caíste en todos los tiempos, fuiste en la dirección pedida, pero tu postura se levantó y tus rodillas quedaron estiradas. ¿Cuántos criterios de tiempo, espacio y cuerpo cumpliste?", ["Cumples tiempo y espacio.", "Falla el cuerpo por las rodillas estiradas.", "Cumples 2 de 3."], "2 de 3"),
   ("Elegir el ajuste", "Una persona se adelanta a la cuenta en el paso 5. Quiere probar cuatro cambios a la vez. ¿Qué conviene más?", ["Con varios cambios no se sabe cuál ayudó.", "Hay que cambiar una sola cosa.", "Cambia solo el paso 5, contando en voz alta."], "Cambiar una sola cosa, la cuenta del paso 5")],
  [("Cambiar muchas cosas de una vez entre un intento y otro.", "No sabes cuál cambio produjo la mejora.", "Cambia una sola cosa y observa."), ("Creer que ir rápido es bailar bien.", "Sin tiempo ni postura correctos la velocidad solo agrega errores.", "Empieza lento y sube la velocidad cuando salga limpio.")],
  [ex("¿Qué es una danza folclórica: A) un baile propio de un lugar y de una tradición; B) un baile solo para competir?", "A", "Una danza folclórica pertenece a una tradición y a un lugar."),
   ex("En tu patrón de 8 tiempos hay 4 pasos laterales. ¿Cuántos tiempos ocupan en total los dos cierres de pies y la pausa?", "4", "Los 8 tiempos menos los 4 de los pasos laterales dejan 2 de cierre y 2 de pausa."),
   ex("¿Quién enseña los pasos concretos de una danza folclórica: A) quien la conoce, como una profesora o una persona de la comunidad; B) cualquier video sin revisar?", "A", "Los pasos tradicionales se aprenden con personas que conocen la tradición.")],
  [ex("Se evalúa si caes en la cuenta correcta de la música. ¿Qué criterio es: tiempo, espacio o cuerpo?", "Tiempo", "El tiempo se refiere a la cuenta del ritmo."),
   ex("Tus pasos laterales son más cortos de lo indicado. ¿Qué criterio falla: A) espacio; B) tiempo?", "A", "La distancia del paso pertenece al criterio de espacio."),
   ex("¿Cuándo subes la velocidad de la secuencia: A) cuando sale limpia tres veces seguidas; B) apenas aprendes los pasos?", "A", "La velocidad se sube después de dominar el control.")],
  [ex("Probaste el patrón 4 veces: en 3 cumpliste los tres criterios. ¿Cómo anotas tu precisión?", "3 de 4", "Se escriben los aciertos y luego los intentos."),
   arith("El patrón completo tiene 8 tiempos y lo repites 6 veces seguidas. ¿Cuántos tiempos cuentas en total?", "8*6", "Se multiplican los tiempos por las repeticiones.", " tiempos"),
   ex("Observas que pierdes el equilibrio en el cierre de pies. ¿Qué ajustas: A) bajo el centro del cuerpo flexionando las rodillas; B) levanto más los talones?", "A", "Flexionar las rodillas baja el centro del cuerpo y estabiliza.")],
  [ex("Tobías cambió el ritmo, la distancia del paso y la postura entre dos intentos y mejoró. ¿Puede saber qué cambio ayudó: sí o no?", "No", "Al cambiar tres cosas a la vez no se distingue cuál produjo la mejora."),
   ex("Laura dice que bailar bien es hacerlo lo más rápido posible. ¿Tiene razón: sí o no?", "No", "Sin tiempo y postura correctos, la velocidad solo agrega errores.")],
  [arith("Haces 5 series de 4 repeticiones del patrón con 20 segundos de pausa después de cada serie, menos la última. ¿Cuántos segundos de pausa hay en total?", "4*20", "Con 5 series hay 4 pausas de 20 segundos.", " segundos"),
   ex("La pauta de la danza tiene 3 criterios y 5 intentos. Si el máximo de puntos por intento es 3, ¿cuántos puntos puedes sumar como máximo en los 5 intentos?", "15", "Son 3 puntos por intento multiplicados por 5 intentos.")],
  [ex("Una amiga quiere aprender cueca viendo videos sin saber de dónde son. ¿Qué es mejor: A) aprender también con su profesora o con una persona que conozca la tradición; B) copiar el primer video?", "A", "Las danzas folclóricas se aprenden mejor con quienes conocen la tradición."),
   ex("Dos personas del curso comparan quién baila mejor y una se avergüenza. ¿Qué haces: A) propongo que cada una compare sus puntos de hoy con los de la semana pasada; B) sigo comparando?", "A", "La evaluación sirve para mejorar cada una y no para comparar a las personas.")],
  [ex("En Educación Física: ¿qué es un ajuste?", "El cambio de una sola cosa para mejorar el siguiente intento", "Esa es la definición de la clase."),
   ex("¿Cuáles son los tres criterios de precisión en la danza de esta clase?", "Tiempo, espacio y cuerpo", "Son los tres criterios de la pauta."),
   ex("¿Qué haces si sientes dolor o mareo durante el baile?", "Me detengo y aviso a una persona adulta", "La seguridad va antes que terminar el patrón.")],
  ("Practica este patrón de 8 tiempos: 1-2 dos pasos laterales a la derecha, 3 cierre de pies, 4-5 dos pasos laterales a la izquierda, 6 cierre de pies, 7-8 pausa. Haz 5 intentos lentos y revisa con la pauta de tiempo, espacio y cuerpo (1 punto por criterio, máximo 3 por intento). Después de los 3 primeros intentos cambia una sola cosa, por ejemplo contar en voz alta o acortar el paso, y haz 2 intentos más. Anota los puntos de cada intento y escribe si el ajuste ayudó. La persona de tu casa puede marcar la lista.",
   "Puntos: intento 1: 2, intento 2: 2, intento 3: 3. Cambio: conté en voz alta. Intento 4: 3, intento 5: 3. Total: 13 de 15. El ajuste ayudó porque corrigió que me adelantaba en el tiempo 4. Una danza folclórica real la aprendería con mi profesora o una persona de la comunidad.",
   ["revisa tiempo, espacio y cuerpo en cada intento", "cambia una sola cosa después del tercer intento", "compara los puntos antes y después del ajuste"],
   ["tabla de cinco intentos con puntos", "descripción del ajuste", "conclusión sobre si ayudó"],
   ["cambiar varias cosas a la vez", "ir rápido antes de que salga limpio", "bailar con dolor o sobre piso resbaladizo"],
   "Explica qué criterio fue el más difícil y cómo lo notaste."),
  "Haz solo 3 intentos lentos y marca cuántos criterios cumples en cada uno.",
  "Averigua con tu profesor o una persona de la comunidad qué danza folclórica se baila en tu zona y anota una característica general.")
